window.kbPageData["views/entry/k-c17e3a0ec3665227"] = {"key":"entry/k-c17e3a0ec3665227","state":{"route":"entry/k-c17e3a0ec3665227"},"node":{"id":"k-c17e3a0ec3665227","mode":"k","title":"科学社会主义的基本原则 · 科学社会主义基本原则的主要内容","type":"原理与机制","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"主类":["原理与机制"],"出处性质":["理论手册"],"学科":["政治理论"],"来源主题":["科学社会主义"],"资料类别":["非时政"]},"directorySummary":"一、科学社会主义基本原则的主要内容\n1.人类社会发展规律和资本主义基本矛盾是“资本主义必然灭亡、社会主义必然胜利的”\n根本依据。\n2.无产阶级是最先进最革命的阶级，肩负着推翻资本主义旧世界、建立社会主义和共产\n主义新世界的历史使命。\n3.无产阶级革命是无产阶级进行斗争的最高形式，以建立无产阶级专政的…","sources":[{"id":"2ff92042ed2ab285","label":"科学社会主义的基本原则 · 科学社会主义基本原则的主要内容","topic":"科学社会主义","category":"非时政","text":"一、科学社会主义基本原则的主要内容\n1.人类社会发展规律和资本主义基本矛盾是“资本主义必然灭亡、社会主义必然胜利的”\n根本依据。\n2.无产阶级是最先进最革命的阶级，肩负着推翻资本主义旧世界、建立社会主义和共产\n主义新世界的历史使命。\n3.无产阶级革命是无产阶级进行斗争的最高形式，以建立无产阶级专政的国家为目的。\n4.在生产资料公有制基础上组织生产，满足全体社会成员的需要是社会主义生产的根本\n目的。\n5.对社会生产进行有计划的指导和调节，实行等量劳动领取等量产品的按劳分配原则。\n6.社会主义社会要合乎自然规律地改造和利用自然，努力实现人与自然的和谐共生。\n7. 社会主义必须坚持科学理论指导，发展先进文化。\n8.无产阶级政党是无产阶级的先锋队，社会主义事业必须始终坚持无产阶级政党的领导。\n9.通过无产阶级专政和社会主义高度发展，最终实现向消灭阶级、消灭剥削、实现人的\n而自由发展的共产主义社会的过渡。","source":{"doc":"3ccc56f4000d1642c2d1","first":12,"last":12,"page":12,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"questions":{},"terms":{},"references":{},"topics":[],"units":{"k-c17e3a0ec3665227":[]}};
